<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import AppPage from '../../components/common/AppPage.vue'; import StatusBadge from '../../components/common/StatusBadge.vue'; import EmptyState from '../../components/common/EmptyState.vue'; import ErrorState from '../../components/common/ErrorState.vue'; import { getCase, getCaseHistory } from '../../api/case'; import type { CheckpointHistoryItem, MedicalCase } from '../../types/case'; import { formatDateTime } from '../../utils/format'
const route = useRoute(); const router = useRouter(); const id = String(route.params.caseId); const current = ref<MedicalCase | null>(null); const history = ref<CheckpointHistoryItem[]>([]); const loading = ref(true); const error = ref(''); const selected = ref<CheckpointHistoryItem | null>(null)
const labels: Record<string, string> = { initial: '病例创建', prepare: '准备患者资料', risk_screening: '完成风险筛查', medical_agent: '完成综合医学分析', specialist_router: '完成专科路由', cardiology_prepare: '准备心内科分析', cardiology_agent: '完成心内科专业分析', cardiology_result: '汇总心内科意见', gastroenterology_prepare: '准备消化科分析', gastroenterology_agent: '完成消化科专业分析', gastroenterology_result: '汇总消化科意见', synthesis: '生成 AI 辅助意见', doctor_review: '医生完成审核', finalize: '形成最终审核结果' }
const ordered = computed(() => [...history.value].reverse().filter((item, index) => item.stage !== 'initial' || index === 0));
const changes = computed(() => { const ai = current.value?.ai_result; const doctor = current.value?.doctor_result; if (!ai || !doctor) return []; const result: Array<{ field: string; before: string; after: string }> = []; if (ai.clinical_summary !== doctor.clinical_summary) result.push({ field: '临床摘要', before: ai.clinical_summary, after: doctor.clinical_summary }); if (ai.risk_level !== doctor.risk_level) result.push({ field: '风险等级', before: ai.risk_level, after: doctor.risk_level }); const beforeTests = ai.recommended_tests.join('、'); const afterTests = doctor.recommended_tests.join('、'); if (beforeTests !== afterTests) result.push({ field: '建议检查', before: beforeTests, after: afterTests }); const beforeConditions = ai.possible_conditions.map(i => i.name).join('、'); const afterConditions = doctor.possible_conditions.map(i => i.name).join('、'); if (beforeConditions !== afterConditions) result.push({ field: '鉴别诊断', before: beforeConditions, after: afterConditions }); return result })
async function load() { loading.value = true; try { [current.value, history.value] = await Promise.all([getCase(id), getCaseHistory(id)]) } catch { error.value = '诊断历史加载失败' } finally { loading.value = false } } onMounted(load)
</script>
<template><AppPage title="诊断复盘" description="以业务时间线回顾 AI 分析、医生审核与最终结果"><template #actions><el-button @click="router.push(`/cases/${id}`)">返回病例工作台</el-button></template><el-skeleton v-if="loading" :rows="10" animated /><ErrorState v-else-if="error" :message="error" @retry="load" /><template v-else-if="current"><section class="history-summary surface"><div><small>病例号</small><strong class="mono">{{ current.id }}</strong></div><div><small>病例状态</small><StatusBadge type="status" :value="current.status" /></div><div><small>风险等级</small><StatusBadge type="risk" :value="current.risk_level" /></div><div><small>创建时间</small><strong>{{ formatDateTime(current.created_at) }}</strong></div></section><div class="history-grid"><section class="surface timeline-card"><h2 class="section-title">诊断执行轨迹</h2><p class="section-subtitle">点击节点查看当时的业务状态摘要</p><div v-if="ordered.length" class="history-timeline"><button v-for="item in ordered" :key="`${item.checkpoint_id}-${item.stage}`" @click="selected = item"><time>{{ item.created_at ? new Date(item.created_at).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) : '—' }}</time><span /><div><strong>{{ labels[item.stage] || '处理临床信息' }}</strong><p v-if="item.risk_level">风险等级：{{ item.risk_level }}</p><p v-if="item.status">业务状态：{{ item.status }}</p></div></button></div><EmptyState v-else title="暂无可展示的诊断轨迹" /></section><aside class="surface state-card"><h2 class="section-title">状态摘要</h2><template v-if="selected"><dl><div><dt>阶段</dt><dd>{{ labels[selected.stage] || selected.stage }}</dd></div><div><dt>时间</dt><dd>{{ formatDateTime(selected.created_at) }}</dd></div><div><dt>风险</dt><dd>{{ selected.risk_level || '尚未分级' }}</dd></div><div><dt>状态</dt><dd>{{ selected.status || '处理中' }}</dd></div><div><dt>AI 草稿</dt><dd>{{ selected.has_draft ? '已生成' : '尚未生成' }}</dd></div><div><dt>医生审核</dt><dd>{{ selected.has_review ? '已完成' : '尚未完成' }}</dd></div></dl></template><EmptyState v-else title="选择一个时间节点" description="这里仅展示业务摘要，不暴露 Checkpoint 原始 State" /></aside></div><section v-if="current.ai_result && current.doctor_result" class="surface comparison"><header><div><h2 class="section-title">AI 原始意见与医生最终意见</h2><p class="section-subtitle">用于临床复盘与模型效果分析</p></div></header><div v-if="changes.length" class="diff-list"><article v-for="item in changes" :key="item.field"><h3>{{ item.field }}</h3><div><span>AI 原始</span><p>{{ item.before || '无' }}</p></div><div class="after"><span>医生最终</span><p>{{ item.after || '无' }}</p></div></article></div><div v-else class="same">医生审核通过，最终意见与 AI 原始草稿一致。</div><div v-if="current.review_reason" class="review-note"><strong>医生补充意见</strong><p>{{ current.review_reason }}</p></div></section></template></AppPage></template>
<style scoped lang="scss">.history-summary { display: grid; grid-template-columns: 1.5fr repeat(3, 1fr); gap: 20px; padding: 18px 20px; margin-bottom: 18px; }.history-summary div { display: grid; gap: 7px; }.history-summary small { color: var(--text-tertiary); }.history-grid { display: grid; grid-template-columns: 1.4fr .8fr; gap: 18px; }.timeline-card, .state-card, .comparison { padding: 22px; }.history-timeline { margin-top: 22px; }.history-timeline button { width: 100%; border: 0; background: transparent; display: grid; grid-template-columns: 55px 18px 1fr; gap: 10px; text-align: left; cursor: pointer; min-height: 70px; padding: 0; }.history-timeline time { color: var(--text-tertiary); font-size: 11px; padding-top: 2px; }.history-timeline span { width: 10px; height: 10px; background: var(--secondary); border-radius: 50%; position: relative; }.history-timeline span::after { content: ''; width: 1px; background: var(--border); position: absolute; top: 10px; bottom: -60px; left: 4px; }.history-timeline button:last-child span::after { display: none; }.history-timeline strong { font-size: 13px; }.history-timeline p { margin: 5px 0 0; color: var(--text-secondary); font-size: 11px; }.state-card dl { margin: 18px 0 0; }.state-card dl div { padding: 11px 0; border-top: 1px solid var(--border); }.state-card dt { color: var(--text-tertiary); font-size: 11px; }.state-card dd { margin: 5px 0 0; font-size: 13px; }.comparison { margin-top: 18px; }.diff-list { display: grid; gap: 12px; margin-top: 18px; }.diff-list article { display: grid; grid-template-columns: 130px 1fr 1fr; border: 1px solid var(--border); border-radius: 10px; overflow: hidden; }.diff-list h3 { margin: 0; padding: 15px; font-size: 13px; background: var(--soft-surface); }.diff-list div { padding: 13px 16px; }.diff-list div span { color: var(--text-tertiary); font-size: 10px; }.diff-list div p { margin: 6px 0 0; font-size: 12px; line-height: 1.55; }.diff-list .after { background: #f0fdf9; }.same, .review-note { margin-top: 18px; padding: 15px; background: #f0fdf4; color: #166534; border-radius: 9px; font-size: 13px; }.review-note p { color: var(--text-secondary); }@media(max-width: 900px) { .history-summary { grid-template-columns: 1fr 1fr; }.history-grid { grid-template-columns: 1fr; }.diff-list article { grid-template-columns: 1fr; } }</style>
